import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8
#define THREADS_X 16
#define THREADS_Y 16

__global__ void sgemm_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K) {
    __shared__ float As[BK][BM];
    __shared__ float Bs[BK][BN];

    int bx = blockIdx.x; // along N
    int by = blockIdx.y; // along M

    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15
    int tid = ty * THREADS_X + tx; // 0..255

    float accum[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            accum[i][j] = 0.0f;
        }
    }

    int rowBase = by * BM;
    int colBase = bx * BN;

    int numKTiles = K / BK;

    for (int t = 0; t < numKTiles; t++) {
        int k0 = t * BK;

        // Load A tile: BM x BK = 128*8 = 1024 elements, 256 threads -> 4 per thread
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int idx = tid * 4 + i;
            int r = idx / BK;
            int c = idx % BK;
            int gRow = rowBase + r;
            int gCol = k0 + c;
            As[c][r] = A[gRow * K + gCol];
        }

        // Load B tile: BK x BN = 8*128 = 1024 elements, 256 threads -> 4 per thread
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int idx = tid * 4 + i;
            int r = idx / BN;
            int c = idx % BN;
            int gRow = k0 + r;
            int gCol = colBase + c;
            Bs[r][c] = B[gRow * N + gCol];
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; kk++) {
            float regA[TM];
            float regB[TN];

            #pragma unroll
            for (int i = 0; i < TM; i++) {
                regA[i] = As[kk][ty * TM + i];
            }
            #pragma unroll
            for (int j = 0; j < TN; j++) {
                regB[j] = Bs[kk][tx * TN + j];
            }

            #pragma unroll
            for (int i = 0; i < TM; i++) {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    accum[i][j] += regA[i] * regB[j];
                }
            }
        }

        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < TM; i++) {
        int outRow = rowBase + ty * TM + i;
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            int outCol = colBase + tx * TN + j;
            C[outRow * N + outCol] = accum[i][j];
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    dim3 blockDim(THREADS_X, THREADS_Y);
    dim3 gridDim(N / BN, M / BM);

    sgemm_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs square matrix multiplication (C = A * B)
    using a custom tiled CUDA SGEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda()
        B = B.cuda()
        return self.matmul.matmul_cuda(A, B)


N = 2048 * 2

def get_inputs():
    A = torch.rand(N, N)
    B = torch.rand(N, N)
    return [A, B]

def get_init_inputs():
    return []

